CREATE SEQUENCE truss.action_store_control_seq AS bigint MINVALUE 1 MAXVALUE 9223372036854775807 NO CYCLE; CREATE TABLE truss.action_store_registration (singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton), control_id bigint NOT NULL UNIQUE DEFAULT nextval('truss.action_store_control_seq') CHECK (control_id > 0), logical_store_id uuid NOT NULL UNIQUE, store_identity bytea NOT NULL UNIQUE CHECK (store_identity = convert_to(('"' || logical_store_id::text) || '"', 'UTF8')), tenant_identity bytea NOT NULL CHECK (octet_length(tenant_identity) BETWEEN 1 AND 4096), executor_oids oid[] NOT NULL CHECK (cardinality(executor_oids) BETWEEN 0 AND 4), guard_epoch uuid NOT NULL UNIQUE CHECK (guard_epoch <> logical_store_id), epoch_identity bytea NOT NULL CHECK (epoch_identity = convert_to(('"' || guard_epoch::text) || '"', 'UTF8')), registration_key bytea NOT NULL UNIQUE CHECK (octet_length(registration_key) BETWEEN 1 AND 256), installation_id uuid NOT NULL REFERENCES truss.catalog_runtime_installation (installation_id), source_installation_id text GENERATED ALWAYS AS (installation_id::text) STORED, database_oid oid NOT NULL CHECK (database_oid <> '0'::oid), schema_oid oid NOT NULL CHECK (schema_oid <> '0'::oid), postmaster_started_at timestamptz NOT NULL CHECK (isfinite(postmaster_started_at)), source_epoch text NOT NULL CHECK (octet_length(source_epoch) BETWEEN 1 AND 256), source_incarnation text NOT NULL CHECK (octet_length(source_incarnation) BETWEEN 1 AND 1024), source_profile_bytes bytea NOT NULL CHECK (octet_length(source_profile_bytes) BETWEEN 1 AND 65536), source_evidence_bytes bytea NOT NULL CHECK (octet_length(source_evidence_bytes) BETWEEN 1 AND 1048576), runtime_release_id text NOT NULL CHECK (octet_length(runtime_release_id) BETWEEN 1 AND 1024), runtime_release_sha256 bytea NOT NULL CHECK (octet_length(runtime_release_sha256) = 32), issuer_xid xid8 NOT NULL CHECK (issuer_xid > '0'::xid8), issuer_actor_oid oid NOT NULL CHECK (issuer_actor_oid <> '0'::oid), issued_at timestamptz NOT NULL CHECK (isfinite(issued_at)), initial_receipt_bytes bytea NOT NULL CHECK (octet_length(initial_receipt_bytes) BETWEEN 1 AND 4194304), profile_id text NOT NULL CHECK (profile_id = 'truss.action-store/native-pg18/0.1'), FOREIGN KEY (source_installation_id, source_epoch) REFERENCES truss.source_epoch_registry (installation_id, source_epoch)); CREATE TRIGGER action_store_registration_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON truss.action_store_registration EXECUTE FUNCTION truss.catalog_immutable(); ALTER TABLE truss.action_store_registration ENABLE ALWAYS TRIGGER action_store_registration_immutable; REVOKE ALL ON truss.action_store_registration FROM public; REVOKE ALL ON SEQUENCE truss.action_store_control_seq FROM public; REVOKE ALL ON TYPE truss.action_store_registration FROM public